import std.io
import std.string

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let a = string.parseFloat("1.0e999")
    match a {
        Some(w) => { io.println("up-bad ${w}") }
        None => { io.println("up-none") }
    }
    let b = string.parseFloat("1.0e-999")
    match b {
        Some(w) => { io.println("down-bad ${w}") }
        None => { io.println("down-none") }
    }
    let c = string.parseFloat("2.5e-320")
    match c {
        Some(w) => { io.println("sub ${w}") }
        None => { io.println("sub-none") }
    }
    let d = string.parseFloat("1e999")
    match d {
        Some(w) => { io.println("nodot-bad ${w}") }
        None => { io.println("nodot-none") }
    }
    return Ok(())
}
